import random
import day14_gamedata


def get_random_data():
    list_range = len(day14_gamedata.data) - 1
    return day14_gamedata.data[random.randint(0, list_range)]


def display_option(option_display):
    print(
        f"{option_display['name']} - {option_display['description']} from {option_display['country']}"
    )


# generated by deepseek
def get_user_choice():
    while True:
        try:
            choice = input(">")

            if choice not in ["a", "b"]:
                raise ValueError(f"Invalid choice '{choice}'. Must be 'a' or 'b'.")

            return choice

        except ValueError as e:
            print(f"Error: {e}")
            print("Please try again.\n")


def high_or_lower():
    # pick 2 random personalities/topics
    option = {}
    option["a"] = get_random_data()
    option["b"] = get_random_data()
    score = 0

    is_game_on = True
    while is_game_on:
        display_option(option["a"])
        print("VS")
        display_option(option["b"])

        # if they're equal pick a new one, if loop runs for more than 10 iterations it stops and program exits
        counter = 0
        while option["a"]["follower_count"] == option["b"]["follower_count"]:
            counter = counter + 1
            if counter >= 10:
                print("Infinite loop! byebye")
                exit()
            option["b"] = get_random_data()

        # ask user what is higher
        print("")
        print("Which one has more followers (a/b)?")
        choice = get_user_choice()

        # display follower count
        print(
            option["a"]["name"]
            + ": "
            + str(option["a"]["follower_count"])
            + " and "
            + option["b"]["name"]
            + ": "
            + str(option["b"]["follower_count"])
        )

        # if user_pick is lower than the other one = lose
        if (
            choice == "a"
            and option["a"]["follower_count"] <= option["b"]["follower_count"]
        ) or (
            choice == "b"
            and option["b"]["follower_count"] <= option["a"]["follower_count"]
        ):
            print(f"You lose :( - Score: {score}")
            is_game_on = False

        # else, keep the one user picked, generate a random one for the other
        else:
            score = score + 1
            print(f"Correct! Score: {score}")
            print("################################\n")
            # selects a random one to change
            new_choice = random.choice(["a", "b"])
            option[new_choice] = get_random_data()


high_or_lower()
